/**
 * @suppress
 */
public object FfiConverterTypeScoreboardClient: FfiConverter<ScoreboardClient, Pointer> {

    override fun lower(value: ScoreboardClient): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): ScoreboardClient {
        return ScoreboardClient(value)
    }

    override fun read(buf: ByteBuffer): ScoreboardClient {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: ScoreboardClient) = 8UL

    override fun write(value: ScoreboardClient, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * One screen of the troubleshooting guide: the panel state it names, and
 * what to do about it. `slug` keys the server's `/guide/{slug}.png` preview.
 */
data class GuideCopy (
    var `slug`: kotlin.String, 
    var `title`: kotlin.String, 
    var `advice`: kotlin.String
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGuideCopy: FfiConverterRustBuffer<GuideCopy> {
    override fun read(buf: ByteBuffer): GuideCopy {
        return GuideCopy(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: GuideCopy) = (
            FfiConverterString.allocationSize(value.`slug`) +
            FfiConverterString.allocationSize(value.`title`) +
            FfiConverterString.allocationSize(value.`advice`)
    )

    override fun write(value: GuideCopy, buf: ByteBuffer) {
            FfiConverterString.write(value.`slug`, buf)
            FfiConverterString.write(value.`title`, buf)
            FfiConverterString.write(value.`advice`, buf)
    }
}



