/**
 * Implemented on the Swift/Kotlin side to receive pushed state.
 */
public interface ClientListener {
    
    fun `onConnection`(`connected`: kotlin.Boolean)
    
    fun `onBoardState`(`boardId`: kotlin.String, `nowShowing`: List<UiGame>, `online`: kotlin.Boolean)
    
    fun `onCatalog`(`sports`: List<UiSport>)
    
    /**
     * The off modes THIS server offers, in menu order. Delivered with the
     * catalog. The app renders them generically — it must never branch on an
     * id, or forks start needing app releases again.
     */
    fun `onOffModes`(`modes`: List<UiOffMode>)
    
    /**
     * True while the board is inside its quiet window right now. Derived by
     * the server per push — the window is the setting, this is what it means.
     */
    fun `onQuietActive`(`boardId`: kotlin.String, `active`: kotlin.Boolean)
    
    fun `onConfig`(`boardId`: kotlin.String, `config`: UiBoardConfig)
    
    fun `onGames`(`games`: List<UiGame>)
    
    /**
     * A rendered frame arrived (pushed over the WS). `rgba` is 64×32 RGBA8 bytes.
     */
    fun `onFrame`(`frameId`: kotlin.String, `rgba`: kotlin.ByteArray)
    
    fun `onPaired`(`boardId`: kotlin.String)
    
    fun `onPairFailed`(`reason`: kotlin.String)
    
    /**
     * Where to read a board's console, after `set_debug_log` turned it on.
     * Path only (the app joins it to the server it is already talking to).
     * Carries a token that dies with the debug window, so it is a capability
     * and not a permanent address.
     */
    fun `onDebugUrl`(`boardId`: kotlin.String, `url`: kotlin.String)
    
    /**
     * A board's exported settings arrived (the reply to `export_settings`);
     * `json` is the portable blob to share/copy.
     */
    fun `onSettingsExport`(`boardId`: kotlin.String, `json`: kotlin.String)
    
    /**
     * Outcome of `import_settings`: `None` = applied, `Some` = readable error.
     */
    fun `onImportResult`(`boardId`: kotlin.String, `error`: kotlin.String?)
    
    /**
     * Firmware versions, delivered with every board state push: `version` is
     * what the device last reported on this connection (None while offline or
     * pre-report); `update_available` is the server-hosted image's version,
     * present ONLY when it is strictly newer than `version` — show an Update
     * button exactly when this is Some.
     */
    fun `onBoardVersion`(`boardId`: kotlin.String, `version`: kotlin.String?, `updateAvailable`: kotlin.String?)
    
    /**
     * The full firmware menu the server hosts (reply to `list_firmware`) —
     * one image per channel with a current dist, across ALL channels
     * regardless of any board's enrollment. Global to the server, not per
     * board. Drives the DEBUG firmware picker.
     */
    fun `onFirmwareList`(`images`: List<UiFwImage>)
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceClientListener {
    internal object `onConnection`: UniffiCallbackInterfaceClientListenerMethod0 {
        override fun callback(`uniffiHandle`: Long,`connected`: Byte,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeClientListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onConnection`(
                    FfiConverterBoolean.lift(`connected`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `onBoardState`: UniffiCallbackInterfaceClientListenerMethod1 {
        override fun callback(`uniffiHandle`: Long,`boardId`: RustBuffer.ByValue,`nowShowing`: RustBuffer.ByValue,`online`: Byte,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeClientListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onBoardState`(
                    FfiConverterString.lift(`boardId`),
                    FfiConverterSequenceTypeUiGame.lift(`nowShowing`),
                    FfiConverterBoolean.lift(`online`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
