    internal object `onCatalog`: UniffiCallbackInterfaceClientListenerMethod2 {
        override fun callback(`uniffiHandle`: Long,`sports`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
